1	package televibe
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"sync"
8		"time"
9	
10		"github.com/gravitational/teleport/api/client"
11		"github.com/gravitational/teleport/api/types"
12		"golang.org/x/sync/errgroup"
13	
14		"televibe/ai"
15		"televibe/jira"
16		"televibe/reputation"
17		"televibe/risk"
18		"televibe/telemetry"
19	)
20	
21	type App struct {
22		cfg    *Config
23		tele   *client.Client
24		ai     ai.Provider
25		jira   *jira.Client
26		scorer *risk.Scorer
27		rep    *reputation.Store
28		meter  *telemetry.Meter
29	
30		pending   map[string]string
31		pendingMu sync.Mutex
32	}
33	
34	func NewApp(ctx context.Context, cfg *Config) (*App, error) {
35		tele, err := client.New(ctx, client.Config{
36			Addrs: []string{cfg.Teleport.Addr},
37			Credentials: []client.Credentials{
38				client.LoadIdentityFile(cfg.Teleport.IdentityFile),
39			},
40		})
41		if err != nil {
42			return nil, fmt.Errorf("teleport client: %w", err)
43		}
44	
45		prov, err := ai.New(cfg.AI)
46		if err != nil {
47			return nil, fmt.Errorf("ai provider: %w", err)
48		}
49	
50		jc, err := jira.New(cfg.Jira)
51		if err != nil {
52			return nil, fmt.Errorf("jira client: %w", err)
53		}
54	
55		scorer, err := risk.NewScorer(cfg.Risk)
56		if err != nil {
57			return nil, fmt.Errorf("scorer: %w", err)
58		}
59	
60		store, err := reputation.NewStore(cfg.Reputation)
61		if err != nil {
62			return nil, fmt.Errorf("reputation store: %w", err)
63		}
64	
65		var meter *telemetry.Meter
66		if cfg.Telemetry.Enabled {
67			meter, err = telemetry.New(ctx, cfg.Telemetry, store)
68			if err != nil {
69				return nil, fmt.Errorf("telemetry: %w", err)
70			}
71		}
72	
73		return &App{
74			cfg:     cfg,
75			tele:    tele,
76			ai:      prov,
77			jira:    jc,
78			scorer:  scorer,
79			rep:     store,
80			meter:   meter,
81			pending: map[string]string{},
82		}, nil
83	}
84	
85	// Close flushes outstanding telemetry. Safe to call even if telemetry
86	// is disabled.
87	func (a *App) Close(ctx context.Context) error {
88		return a.meter.Shutdown(ctx)
89	}
90	
91	func (a *App) Run(ctx context.Context) error {
92		slog.Info("televibe starting",
93			"provider", a.cfg.AI.Provider,
94			"threshold", a.cfg.Risk.TicketThreshold,
95			"itsm_project", a.cfg.Jira.Project)
96	
97		if err := a.rehydrate(ctx); err != nil {
98			return fmt.Errorf("rehydrate open ITSM tickets: %w", err)
99		}
100	
101		g, gctx := errgroup.WithContext(ctx)
102		g.Go(func() error { return a.watchRequests(gctx) })
103		g.Go(func() error { return a.pollITSM(gctx) })
104		return g.Wait()
105	}
106	
107	func (a *App) rehydrate(ctx context.Context) error {
108		open, err := a.jira.ListOpenTeleportTickets(ctx)
109		if err != nil {
110			return err
111		}
112		a.pendingMu.Lock()
113		for reqID, ticket := range open {
114			a.pending[reqID] = ticket
115		}
116		a.pendingMu.Unlock()
117		slog.Info("rehydrated pending tickets", "count", len(open))
118		return nil
119	}
120	
121	func (a *App) watchRequests(ctx context.Context) error {
122		watcher, err := a.tele.NewWatcher(ctx, types.Watch{
123			Kinds: []types.WatchKind{{Kind: types.KindAccessRequest}},
124		})
125		if err != nil {
126			return fmt.Errorf("start watcher: %w", err)
127		}
128		defer watcher.Close()
129	
130		for {
131			select {
132			case <-ctx.Done():
133				return ctx.Err()
134			case <-watcher.Done():
135				return watcher.Error()
136			case ev := <-watcher.Events():
137				if ev.Type != types.OpPut {
138					continue
139				}
140				req, ok := ev.Resource.(types.AccessRequest)
141				if !ok {
142					continue
143				}
144				if req.GetState() != types.RequestState_PENDING {
145					continue
146				}
147				a.pendingMu.Lock()
148				_, held := a.pending[req.GetName()]
149				a.pendingMu.Unlock()
150				if held {
151					continue
152				}
153				go a.handleRequest(ctx, req)
154			}
155		}
156	}
157	
158	func (a *App) handleRequest(ctx context.Context, req types.AccessRequest) {
159		id := req.GetName()
160		user := req.GetUser()
161		log := slog.With("request_id", id, "user", user)
162	
163		log.Info("scoring access request")
164		result, err := a.scorer.Score(ctx, a.ai, req)
165		if err != nil {
166			log.Error("scoring failed", "err", err)
167			return
168		}
169		log.Info("risk scored",
170			"score", result.Score,
171			"tier", result.Tier.Name,
172			"slang", result.Tier.Slang,
173			"components", result.Components)
174	
175		assessment, err := a.rep.Assess(ctx, user, result.Components)
176		if err != nil {
177			log.Warn("reputation update failed", "err", err)
178		}
179		if len(assessment.Penalties) > 0 {
180			reasons := make([]string, 0, len(assessment.Penalties))
181			for _, p := range assessment.Penalties {
182				reasons = append(reasons, p.Reason)
183			}
184			log.Info("reputation docked",
185				"previous", assessment.Previous,
186				"current", assessment.Score,
187				"reasons", reasons)
188		}
189	
190		if result.Score < a.cfg.Risk.TicketThreshold {
191			reason := fmt.Sprintf("televibe: %s (score %d, %q) — auto-approved",
192				result.Tier.Name, result.Score, result.Tier.Slang)
193			if err := a.submitReview(ctx, id, types.RequestState_APPROVED, reason); err != nil {
194				log.Error("auto-approve failed", "err", err)
195			}
196			return
197		}
198	
199		ticket, err := a.jira.CreateITSMTicket(ctx, jira.TicketInput{
200			RequestID:   id,
201			User:        req.GetUser(),
202			Roles:       req.GetRoles(),
203			Reason:      req.GetRequestReason(),
204			Score:       result.Score,
205			Tier:        result.Tier.Name,
206			Slang:       result.Tier.Slang,
207			Components:  result.Components,
208			AIReasoning: result.Reasoning,
209		})
210		if err != nil {
211			log.Error("create ITSM ticket failed", "err", err)
212	
213			return
214		}
215	
216		a.pendingMu.Lock()
217		a.pending[id] = ticket
218		a.pendingMu.Unlock()
219		log.Info("ITSM ticket created, request held for SRE review",
220			"ticket", ticket, "tier", result.Tier.Name, "slang", result.Tier.Slang)
221	}
222	
223	func (a *App) pollITSM(ctx context.Context) error {
224		t := time.NewTicker(a.cfg.Jira.PollInterval)
225		defer t.Stop()
226		for {
227			select {
228			case <-ctx.Done():
229				return ctx.Err()
230			case <-t.C:
231				a.reconcileITSM(ctx)
232			}
233		}
234	}
235	
236	func (a *App) reconcileITSM(ctx context.Context) {
237		a.pendingMu.Lock()
238		snap := make(map[string]string, len(a.pending))
239		for k, v := range a.pending {
240			snap[k] = v
241		}
242		a.pendingMu.Unlock()
243	
244		for requestID, ticket := range snap {
245			status, err := a.jira.TicketStatus(ctx, ticket)
246			if err != nil {
247				slog.Warn("ITSM status check failed", "ticket", ticket, "err", err)
248				continue
249			}
250			var next types.RequestState
251			switch status {
252			case jira.StatusApproved:
253				next = types.RequestState_APPROVED
254			case jira.StatusRejected:
255				next = types.RequestState_DENIED
256			default:
257				continue
258			}
259			reason := fmt.Sprintf("televibe: ITSM %s resolved (%s)", ticket, status)
260			if err := a.submitReview(ctx, requestID, next, reason); err != nil {
261				slog.Error("submit review failed", "request_id", requestID, "err", err)
262				continue
263			}
264			a.pendingMu.Lock()
265			delete(a.pending, requestID)
266			a.pendingMu.Unlock()
267		}
268	}
269	
270	func (a *App) submitReview(ctx context.Context, requestID string, state types.RequestState, reason string) error {
271		_, err := a.tele.SubmitAccessReview(ctx, types.AccessReviewSubmission{
272			RequestID: requestID,
273			Review: types.AccessReview{
274				Author:        "televibe",
275				ProposedState: state,
276				Reason:        reason,
277			},
278		})
279		return err
280	}
