35	func LoadConfig(path string) (*Config, error) {
36		data, err := os.ReadFile(path)
37		if err != nil {
38			return nil, fmt.Errorf("read config: %w", err)
39		}
40		cfg := &Config{}
41		if err := toml.Unmarshal(data, cfg); err != nil {
42			return nil, fmt.Errorf("parse config: %w", err)
43		}
44		cfg.applyDefaults()
45		if err := cfg.validate(); err != nil {
46			return nil, err
47		}
48		return cfg, nil
49	}
50	
51	func (c *Config) applyDefaults() {
52		c.Jira.ApplyDefaults()
53		c.Risk.ApplyDefaults()
54		c.Reputation.ApplyDefaults()
55		c.Telemetry.ApplyDefaults()
56		if c.Log.Level == "" {
57			c.Log.Level = "info"
58		}
59	}
60	
61	func (c *Config) validate() error {
62		if c.Teleport.Addr == "" {
63			return fmt.Errorf("teleport.addr is required")
64		}
65		if c.Teleport.IdentityFile == "" {
66			return fmt.Errorf("teleport.identity_file is required")
67		}
